import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 50 · Christmas recipe: old-fashioned divinity candy (Google Trends 3/11: christmas treat recipes, christmas candy rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, there's one Christmas candy that separates the brave grandmothers from the rest. Divinity. Little white clouds of whipped sugar, with a pecan on top, that melt on your tongue like sweet snow. My Grandma Pearl made it every Christmas, and she said divinity was the only candy that could tell if you'd been to church that week.""",
   "divinity candy pecans plate", "SWEET SNOW")
sc("""Because divinity is fussy, honey. People tell me theirs never set, and stays a sticky puddle, or turns hard and crumbly like chalk. So tonight I'm giving you Grandma Pearl's divinity, every step, and the five mistakes that ruin it. And stay with me, because the last secret is about the weather, and it's the reason most divinity fails before you ever turn on the stove.""",
   "sticky failed candy puddle", "IT NEVER SETS")

ch("Grandma Pearl's candy")
sc("""Divinity is an American candy, from the early nineteen hundreds, when corn syrup came into every kitchen. Nobody knows who named it. Some say the first person who tasted it said, why, this is divine. Others say it got the name because you need divine help to make it right. Grandma Pearl believed the second one.""",
   "early 1900s kitchen candy making", "DIVINE HELP")
sc("""On the farm, she made it the week before Christmas, on a cold, dry morning. She'd beat it by hand with a wooden spoon for twenty minutes, until her arm ached, and then my grandfather would take a turn. They'd pass the bowl back and forth across the kitchen table, bickering the whole time. It was the most romantic thing I ever saw them do.""",
   "old couple kitchen table bowl", "THE MOST ROMANTIC THING")
sc("""Today we have electric mixers, honey, thank the Lord, and it's much easier. A stand mixer is best. But you still have to follow the rules exactly. In a minute I'll tell you the first one, and it's about a tool most people skip, and it costs about ten dollars at the grocery store.""",
   "stand mixer kitchen counter", "A TEN DOLLAR TOOL")

sc("""My first try at divinity was in nineteen sixty-six, for my husband's office party. It was a rainy December day, and I didn't know any better. I beat it for forty minutes, and it never set. I ended up spooning it into little glass dishes and calling it divinity pudding. The men ate it with spoons, and my husband's boss asked for the recipe. I never told him the truth.""",
   "1960s office Christmas party desserts", "DIVINITY PUDDING")

ch("What you need")
sc("""Here's what you need, for about forty pieces. Two and a half cups of white sugar. Half a cup of light corn syrup. Half a cup of water. A quarter teaspoon of salt. Two egg whites, at room temperature. One teaspoon of vanilla. And about a cup of pecan halves, or chopped pecans, toasted. That's all. But every one of these matters.""",
   "sugar corn syrup eggs pecans", "THE INGREDIENTS")
sc("""And the tool I promised. A candy thermometer. Mistake number one is guessing. Divinity has to be cooked to exactly the right temperature, and a few degrees too low, it never sets. A few degrees too high, it turns to chalk. Grandma Pearl tested it by dropping a bit in cold water. You can do that too, but a thermometer is much easier.""",
   "candy thermometer saucepan", "DON'T GUESS")
sc("""And check your thermometer first, sweetheart. Put it in a pot of boiling water. It should read two hundred twelve degrees. If it reads two hundred ten, then it's two degrees off, and you'll need to cook your candy two degrees lower than the recipe says. My thermometer was three degrees off for ten years, and I blamed the weather the whole time.""",
   "thermometer boiling water test", "TEST IT FIRST")

ch("The syrup")
sc("""Step one. Line two baking sheets with wax paper, and set them by the mixer. Have everything ready before you start, because once the candy is done, you have about one minute to work. Then, in a heavy saucepan, stir the sugar, corn syrup, water and salt together over medium heat, just until the sugar dissolves.""",
   "wax paper baking sheets ready", "HAVE EVERYTHING READY")
sc("""Then stop stirring. Mistake number two is stirring the syrup while it boils. It makes sugar crystals form, and the whole batch turns grainy. Clip on the thermometer, and let it boil without touching it. If you see sugar crystals on the sides of the pan, brush them down with a pastry brush dipped in water.""",
   "boiling sugar syrup pan", "STOP STIRRING")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. While the syrup boils, put the egg whites in the bowl of the mixer. When the syrup reaches about two hundred forty degrees, start beating the whites on high, until they form stiff peaks that stand up straight when you lift the beater. Then turn the mixer off and wait.""",
   "egg whites stiff peaks mixer", "STIFF PEAKS")

ch("The temperature")
sc("""Keep boiling the syrup until it reaches exactly two hundred fifty-two degrees. That's called the hard ball stage. If you drop a little in cold water, it makes a firm ball that holds its shape but still gives a little when you squeeze it. That's the number, honey. Two fifty-two. Write it on your hand if you have to.""",
   "candy thermometer 252 degrees", "TWO FIFTY-TWO")
sc("""Now, mistake number three. Pouring the hot syrup in all at once. It cooks the egg whites into scrambled eggs. Turn the mixer on high, and pour the hot syrup into the whites in a very thin stream, like a pencil, down the side of the bowl, not onto the beaters. It takes about a minute. Be careful, the syrup is hotter than boiling water.""",
   "pouring syrup thin stream mixer", "A THIN STREAM")

ch("Beating")
sc("""Step three. Add the vanilla, and keep beating on high. It will be shiny and runny at first, like marshmallow cream. Keep going. Five minutes, eight minutes, sometimes twelve. Mistake number four is stopping too soon. You'll know it's ready when it starts to lose its shine, turns dull and a little matte, and holds its shape when you lift the beater.""",
   "divinity beating mixer bowl", "IT LOSES ITS SHINE")
sc("""Here's the test Grandma Pearl used. Drop a spoonful on the wax paper. If it holds a soft little peak and doesn't spread, it's ready. If it flattens into a puddle, beat it another minute and test again. And when it's ready, stir in the chopped pecans, if you're using them, quickly, with a spoon.""",
   "spoonful divinity on wax paper", "THE SPOON TEST")
sc("""So far, a tested thermometer, no stirring while it boils, stiff egg whites, two fifty-two exactly, a thin stream of syrup, and beat it until it loses its shine. Now work fast, sweetheart. Use two spoons, one to scoop and one to push, and drop little mounds onto the wax paper, with a swirl on top. Press a pecan half on each one.""",
   "dropping candy mounds two spoons", "WORK FAST")
sc("""If it starts to stiffen in the bowl before you're done, add a few drops of hot water and stir. Let the pieces sit at room temperature until they're firm and dry on the outside, about two hours, or overnight. They should be crisp on the outside and soft and creamy inside, like a cloud with a thin shell.""",
   "divinity drying on wax paper", "LIKE A CLOUD")

ch("The weather")
sc("""And now the secret I promised, the one that makes most divinity fail before you start. The weather. Mistake number five is making it on a humid or rainy day. Sugar soaks up the water from the air, and on a damp day, divinity just won't set, no matter what you do. It stays sticky forever. Grandma Pearl always looked out the window before she started.""",
   "rainy day kitchen window", "LOOK OUT THE WINDOW")
sc("""Make it on a cold, clear, dry day. Winter is perfect for that. Don't boil a pot of soup or run the dishwasher at the same time, because the steam makes the kitchen humid. And if you must make it on a damp day, cook the syrup two or three degrees higher, to two fifty-five. Pearl said, a good candy maker reads the sky before she reads the recipe.""",
   "clear cold winter day farm", "READ THE SKY")

sc("""And if it does fail, honey, don't throw it away. If it never sets, spread it on a cake like frosting, or spoon it over ice cream, like my divinity pudding. If it goes too hard and crumbly, break it up and stir it into softened vanilla ice cream with the pecans, and freeze it. Grandma Pearl said, there's no wasted sugar in my kitchen, just sugar that changed its mind.""",
   "candy over vanilla ice cream", "SUGAR THAT CHANGED ITS MIND")

ch("Variations and keeping")
sc("""You can make it pretty for Christmas, honey. Add a few drops of red or green food coloring with the vanilla, for pink or pale green divinity. Or use peppermint extract instead of vanilla, and sprinkle crushed candy canes on top. Or chopped maraschino cherries, well dried. My mother made a plate of white, pink and green, and called it the Christmas tree plate.""",
   "pink green divinity plate", "THE CHRISTMAS TREE PLATE")
sc("""Divinity keeps about two weeks in an airtight tin, with wax paper between the layers, in a cool, dry place. Never in the icebox, because it gets damp and sticky. And it freezes for a month, wrapped tight. It makes a beautiful gift in paper candy cups. Old folks especially love it, sweetheart. One bite, and they're seven years old on the farm again.""",
   "divinity tin paper cups gift", "SEVEN YEARS OLD AGAIN")

ch("Grandma's kitchen")
sc("""So one more time. A cold, dry day. A tested candy thermometer. Stir only until the sugar dissolves, then don't touch it. Stiff egg whites. Exactly two fifty-two. A thin stream of syrup. Beat it until it loses its shine. Work fast, two spoons, a pecan on top. That's Grandma Pearl's divinity, and with a little divine help, it sets every time.""",
   "plate of divinity Christmas", "IT SETS EVERY TIME")
sc("""Tell me in the comments, sweetheart. Did somebody in your family make divinity? And did it ever fail? Be honest, mine has. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas kitchen evening candy", "DID IT EVER FAIL?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma50", "Divinity Candy EVERYONE's Grandma Made (Why Yours Won't SET)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Divinity, an American candy from the early 1900s made with sugar, corn syrup and whipped egg whites; humidity prevents it from setting.",
      "Recipe as written by Grandma Ruth: 2 1/2 cups sugar, 1/2 cup light corn syrup, 1/2 cup water, 1/4 tsp salt, 2 egg whites, 1 tsp vanilla, 1 cup toasted pecans; syrup cooked to 252 F (hard ball)."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
